extends Node3D
## The single authored supply concept: one crate deliberately far from the
## defense line. Pilot picks up one ammo pack (E), deposits into any turret (E).
## Forces leaving the ideal position; never becomes per-turret maintenance.

const DamageEvent := preload("res://combat/src/combat/damage_contract.gd")
const Metrics := preload("res://combat/src/metrics/combat_metrics.gd")
const Stats := preload("res://combat/data/combat_stats.gd")
const ModelLib := preload("res://combat/src/visuals/model_lib.gd")

const INTERACT_RADIUS := 2.6

var destroyed := false
var _hp := 0.0


func _ready() -> void:
	_hp = Stats.ensure().supply_hp
	add_to_group("supply")

	if not ModelLib.attach_sized(self, "SM_Prop_Crate_03.fbx",
			Color(0.25, 0.75, 0.35), Vector3(0, 0.6, 0), 1.1):
		var mesh := MeshInstance3D.new()
		var box := BoxMesh.new()
		box.size = Vector3(1.2, 1.2, 1.2)
		mesh.mesh = box
		mesh.position.y = 0.6
		var m := StandardMaterial3D.new()
		m.albedo_color = Color(0.25, 0.75, 0.35)
		m.emission_enabled = true
		m.emission = Color(0.05, 0.25, 0.08)
		mesh.material_override = m
		add_child(mesh)

	var cs := CollisionShape3D.new()
	var shape := BoxShape3D.new()
	shape.size = Vector3(1.2, 1.2, 1.2)
	cs.shape = shape
	cs.position.y = 0.6
	add_child(cs)


func take_damage(evt) -> void:
	if destroyed or evt.source != DamageEvent.Source.ENEMY:
		return
	_hp -= evt.amount
	Metrics.inst().log_damage(evt, "supply", evt.amount)
	if _hp <= 0.0:
		destroyed = true
		for c in get_children():
			if c is MeshInstance3D:
				c.visible = false


func available() -> bool:
	return not destroyed

extends "res://combat/src/turrets/turret_base.gd"
## MG / sustained DPS: steady hitscan pressure against mass targets. Ammo-limited;
## armored shells reduce it to near-zero — by design it cannot solve armor alone.

const ModelLib := preload("res://combat/src/visuals/model_lib.gd")


func _init() -> void:
	kind = "mg"
	fire_interval = Stats.ensure().mg_interval
	range_f = Stats.ensure().mg_range


func kind_ammo() -> int:
	return Stats.ensure().mg_ammo


func _build_visuals() -> void:
	head = Node3D.new()
	head.position.y = 0.3
	add_child(head)

	if not ModelLib.attach_sized(head, "SM_Prop_Turret_Large_01.fbx",
			Color(0.8, 0.75, 0.35), Vector3.ZERO, 1.1):
		var base := MeshInstance3D.new()
		var cyl := CylinderMesh.new()
		cyl.top_radius = 0.5
		cyl.bottom_radius = 0.7
		cyl.height = 0.6
		base.mesh = cyl
		base.position.y = 0.3
		var bm := StandardMaterial3D.new()
		bm.albedo_color = Color(0.45, 0.5, 0.55)
		base.material_override = bm
		add_child(base)

		var barrel := MeshInstance3D.new()
		var box := BoxMesh.new()
		box.size = Vector3(0.18, 0.18, 1.4)
		barrel.mesh = box
		barrel.position.z = -0.6
		var gm := StandardMaterial3D.new()
		gm.albedo_color = Color(0.8, 0.75, 0.35)
		gm.emission_enabled = true
		gm.emission = Color(0.25, 0.22, 0.05)
		barrel.material_override = gm
		head.add_child(barrel)


func _fire(t) -> void:
	var from := head.global_position
	var to: Vector3 = t.global_position + Vector3.UP * 0.8
	DamageEvent.apply(t, DamageEvent.new(Stats.ensure().mg_damage,
			DamageEvent.Source.MG_TURRET, get_instance_id(), to))
	_beam(from, to, Color(1.0, 0.85, 0.3))


func _beam(from: Vector3, to: Vector3, color: Color) -> void:
	var mi := MeshInstance3D.new()
	var cyl := CylinderMesh.new()
	cyl.top_radius = 0.03
	cyl.bottom_radius = 0.03
	cyl.height = maxf(from.distance_to(to), 0.1)
	mi.mesh = cyl
	mi.position = (from + to) * 0.5
	var m := StandardMaterial3D.new()
	m.albedo_color = color
	m.emission_enabled = true
	m.emission = color * 0.7
	mi.material_override = m
	get_tree().current_scene.add_child(mi)
	var dir := from.direction_to(to)
	if absf(dir.dot(Vector3.UP)) < 0.99:
		mi.look_at(to, Vector3.UP)
	else:
		mi.look_at(to, Vector3.RIGHT)
	mi.rotate_object_local(Vector3.RIGHT, PI * 0.5)
	get_tree().create_timer(0.06).timeout.connect(mi.queue_free)

extends Node3D
## Authored-socket turret base: ammo economy + targeting + damage intake.
## Firing profile lives in subclasses. sim_tick(dt, forced_target) is the pure
## simulation path used by both _physics_process and headless tests.

const DamageEvent := preload("res://combat/src/combat/damage_contract.gd")
const Metrics := preload("res://combat/src/metrics/combat_metrics.gd")
const Stats := preload("res://combat/data/combat_stats.gd")

var kind := "mg"
var hp := 150.0
var max_hp := 150.0
var ammo_max := 120
var ammo := 120
var range_f := 18.0
var fire_interval := 0.12
var cooldown := 0.0
var destroyed := false
var head: Node3D


func _ready() -> void:
	max_hp = Stats.ensure().turret_hp
	hp = max_hp
	ammo = kind_ammo()
	ammo_max = ammo
	add_to_group("turrets")
	_build_visuals()


func kind_ammo() -> int:
	return 0


func _physics_process(dt: float) -> void:
	sim_tick(dt)


func _build_visuals() -> void:
	pass


func sim_tick(dt: float, forced_target = null) -> void:
	if destroyed:
		return
	cooldown -= dt
	if ammo <= 0:
		return
	var t = forced_target if forced_target != null else acquire_target()
	if t == null:
		return
	if is_inside_tree():
		_aim(t)
	if cooldown <= 0.0:
		cooldown = fire_interval
		ammo -= 1
		Metrics.inst().log_shot(kind)
		Metrics.inst().log_ammo_spent(kind, 1)
		_fire(t)


func acquire_target() -> Node3D:
	var best: Node3D = null
	var best_d := range_f
	for e in get_tree().get_nodes_in_group("enemies"):
		if not is_instance_valid(e):
			continue
		var d := global_position.distance_to(e.global_position)
		if d < best_d and _accept(e):
			best = e
			best_d = d
	return best


func _accept(_e) -> bool:
	return true


func _aim(t) -> void:
	var to: Vector3 = t.global_position - global_position
	to.y = 0.0
	if head != null:
		head.rotation.y = atan2(-to.x, -to.z)


func _fire(_t) -> void:
	pass


func take_damage(evt) -> void:
	if destroyed or evt.source != DamageEvent.Source.ENEMY:
		return
	hp -= evt.amount
	Metrics.inst().log_damage(evt, "turret", evt.amount)
	if hp <= 0.0:
		destroyed = true
		remove_from_group("turrets")
		Metrics.inst().turret_destroyed()
		modulate_dark()


func refill(n: int) -> int:
	if destroyed:
		return 0
	var before := ammo
	ammo = mini(ammo_max, ammo + n)
	var delivered := ammo - before
	if delivered > 0:
		Metrics.inst().pack_delivered(delivered)
	return delivered


func modulate_dark() -> void:
	scale *= 0.9


func packed_state() -> Dictionary:
	return {"kind": kind, "ammo": ammo, "hp_frac": snappedf(hp / maxf(max_hp, 1.0), 0.01), "destroyed": destroyed}

extends RefCounted
## Synty model loader. attach_sized() normalizes the model so its largest AABB
## axis equals target_size — no manual scale guessing. Flat role-color material
## override keeps silhouette readability. Falls back (returns false) when a
## file is missing so callers keep primitive geometry; headless never breaks.

const DIR := "res://assets/synty/"


static func attach_sized(parent: Node3D, file: String, color: Color, pos: Vector3,
		target_size: float) -> bool:
	var path := DIR + file
	if not ResourceLoader.exists(path):
		return false
	var ps = load(path)
	if ps == null or not (ps is PackedScene):
		return false
	var inst = ps.instantiate()
	if inst == null or not (inst is Node3D):
		return false
	parent.add_child(inst)
	var aabb := _merged_aabb(inst)
	if aabb.size.length() > 0.001:
		var k := target_size / _max_axis(aabb.size)
		inst.scale = Vector3.ONE * k
	inst.position = pos
	var mat := StandardMaterial3D.new()
	mat.albedo_color = color
	mat.roughness = 0.8
	_paint(inst, mat)
	return true


static func _max_axis(s: Vector3) -> float:
	return maxf(s.x, maxf(s.y, s.z))


static func _merged_aabb(root: Node3D) -> AABB:
	var merged := AABB()
	var first := true
	var stack: Array = [[root, Transform3D.IDENTITY]]
	while not stack.is_empty():
		var top = stack.pop_back()
		var node = top[0]
		var xform: Transform3D = top[1]
		if node is Node3D:
			xform = xform * (node as Node3D).transform
		if node is MeshInstance3D:
			var mi := node as MeshInstance3D
			var ab := xform * mi.get_aabb()
			if first:
				merged = ab
				first = false
			else:
				merged = merged.merge(ab)
		for c in node.get_children():
			stack.append([c, xform])
	return merged


static func find_anim_player(root: Node) -> AnimationPlayer:
	if root is AnimationPlayer:
		return root
	for c in root.get_children():
		var found := find_anim_player(c)
		if found != null:
			return found
	return null


static func _paint(n: Node, mat: Material) -> void:
	if n is MeshInstance3D:
		n.material_override = mat
	for c in n.get_children():
		_paint(c, mat)

extends SceneTree
## Headless test entry:
##   godot --headless --path . --script tests/run_tests.gd
## Pure-logic suites only: motor math, damage contract, turret economy,
## CC behavior, enemy resistances, metrics aggregation. No scene tree needed.

const PilotCommand := preload("res://actor/actor_command.gd")
const PilotState := preload("res://combat/src/pilot/pilot_state.gd")
const PilotMotor := preload("res://combat/src/pilot/pilot_motor.gd")
const DamageEvent := preload("res://combat/src/combat/damage_contract.gd")
const Metrics := preload("res://combat/src/metrics/combat_metrics.gd")
const TurretBase := preload("res://combat/src/turrets/turret_base.gd")
const CCTurret := preload("res://combat/src/turrets/cc_turret.gd")
const EnemyBase := preload("res://combat/src/enemies/enemy_base.gd")
const PressureEnemy := preload("res://combat/src/enemies/pressure_enemy.gd")
const ArmoredEnemy := preload("res://combat/src/enemies/armored_enemy.gd")
const Stats := preload("res://combat/data/combat_stats.gd")

var _failures := 0
var _count := 0


class DummyReceiver:
	var received := 0.0
	func take_damage(evt) -> void:
		received += evt.amount


func check(cond: bool, name: String) -> void:
	_count += 1
	if cond:
		print("PASS  " + name)
	else:
		_failures += 1
		print("FAIL  " + name)


func approx(a: float, b: float, eps := 0.001) -> bool:
	return absf(a - b) <= eps


func _initialize() -> void:
	test_motor()
	test_dodge()
	test_damage_contract()
	test_turret_economy()
	test_cc_behaviour()
	test_enemy_resistances()
	test_metrics()
	print("")
	print("%d checks, %d failures" % [_count, _failures])
	for n in _tracked:
		if is_instance_valid(n):
			n.free()
	quit(_failures)


var _tracked: Array = []


func track(n) -> void:
	_tracked.append(n)


func test_motor() -> void:
	var s := PilotState.new()
	s.yaw = 0.0
	var c := PilotCommand.new()
	c.mv = Vector2(0, -1)
	for i in range(120):
		PilotMotor.step(s, c, 1.0 / 60.0)
	var hspeed := Vector2(s.velocity.x, s.velocity.z).length()
	check(hspeed <= PilotMotor.MAX_SPEED + 0.01 and approx(hspeed, PilotMotor.MAX_SPEED, 0.05),
			"motor: horizontal speed converges to MAX_SPEED")
	check(s.position.z < -5.0, "motor: forward moves along facing (-Z at yaw 0)")

	var s2 := PilotState.new()
	var c2 := PilotCommand.new()
	for i in range(240):
		PilotMotor.step(s2, c2, 1.0 / 60.0)
	check(s2.velocity.y < -10.0, "motor: gravity accumulates when airborne")

	var s3 := PilotState.new()
	s3.grounded = false
	var c3 := PilotCommand.new()
	c3.jump = true
	PilotMotor.step(s3, c3, 1.0 / 60.0)
	check(s3.velocity.y <= 0.0, "motor: jump gated by grounded flag")

	var s4 := PilotState.new()
	s4.grounded = true
	var c4 := PilotCommand.new()
	c4.mv = Vector2(0, -1)
	c4.jump = true
	PilotMotor.step(s4, c4, 1.0 / 60.0)
	check(approx(s4.velocity.y, PilotMotor.JUMP_SPEED), "motor: jump impulse when grounded")

	var a := PilotState.new()
	a.yaw = 1.234
	var b := PilotState.new()
	b.yaw = 1.234
	var ca := PilotCommand.new()
	ca.mv = Vector2(0.6, -0.8)
	ca.jump = true
	ca.look.x = 12.0 * PilotCommand.INPUT_LOOK_SENSITIVITY * PilotCommand.TICK_HZ
	for i in range(100):
		PilotMotor.step(a, ca, 1.0 / 60.0)
		PilotMotor.step(b, ca.duplicate(), 1.0 / 60.0)
	check(a.position.distance_to(b.position) < 0.0001 and approx(a.yaw, b.yaw),
			"motor: deterministic given identical commands")


func test_dodge() -> void:
	var s := PilotState.new()
	s.grounded = true
	var c := PilotCommand.new()
	c.dodge = true
	PilotMotor.step(s, c, 1.0 / 60.0)
	check(s.dodge_left > 0.0 and s.velocity.length() > PilotMotor.MAX_SPEED,
			"dodge: burst exceeds run speed, timer started")
	var before_left := s.dodge_left
	var c2 := PilotCommand.new()
	c2.dodge = true
	PilotMotor.step(s, c2, 1.0 / 60.0)
	check(s.dodge_cd > 0.0 and s.dodge_left <= before_left,
			"dodge: cooldown blocks immediate re-dodge")


func test_damage_contract() -> void:
	var evt := DamageEvent.new(10.0, DamageEvent.Source.PILOT_GUN, 7, Vector3.ONE, false)
	check(approx(evt.amount, 10.0) and evt.source_name() == "pilot_gun",
			"contract: event fields + source name")

	var dummy := DummyReceiver.new()
	check(DamageEvent.apply(dummy, evt), "contract: duck-typed receiver accepts event")
	check(approx(dummy.received, 10.0), "contract: receiver got payload")
	check(not DamageEvent.apply(null, evt), "contract: null target safe no-op")
	check(not DamageEvent.apply(Node3D.new(), evt),
			"contract: object without take_damage rejected")


func test_turret_economy() -> void:
	var t := TurretBase.new()
	track(t)
	t.kind = "mg"
	t.fire_interval = 0.12
	t.ammo = 120
	t.ammo_max = 120
	Metrics.reset_all()
	var target := Node3D.new()
	track(target)
	target.position = Vector3(0, 0, -10)
	var ticks := 0
	while t.ammo > 0 and ticks < 4000:
		t.sim_tick(1.0 / 60.0, target)
		ticks += 1
	check(t.ammo == 0, "turret: drains fully under continuous fire")
	check(int(Metrics.inst().ammo_spent.get("mg", 0)) == 120,
			"turret: every spent round is one logged shot")
	check(ticks >= 120 * 7 and ticks <= 120 * 9,
			"turret: fire rate respects interval (%d ticks)" % ticks)

	for i in range(30):
		t.sim_tick(1.0 / 60.0, target)
	check(int(Metrics.inst().ammo_spent.get("mg", 0)) == 120,
			"turret: dry turret does not fire")

	var delivered := t.refill(200)
	check(delivered == 120 and t.ammo == 120,
			"turret: refill clamps to ammo_max, returns delivered")

	t.take_damage(DamageEvent.new(9999, DamageEvent.Source.ENEMY))
	check(t.destroyed, "turret: enemy fire destroys turret")
	check(t.refill(50) == 0, "turret: destroyed turret refuses resupply")


func test_cc_behaviour() -> void:
	Metrics.reset_all()
	EnemyBase.stats = Stats.ensure()
	var e := PressureEnemy.new()
	track(e)
	e.apply_slow(Stats.ensure().cc_slow_factor, 2.6)
	check(approx(e.slow_factor, Stats.ensure().cc_slow_factor), "cc: slow factor applied")
	check(e.slow_left > 2.5, "cc: slow duration set")
	e.apply_slow(0.5, 1.0)
	check(e.slow_left > 2.5, "cc: reapplication does not shorten slow")

	var cc := CCTurret.new()
	track(cc)
	var slowed := PressureEnemy.new()
	track(slowed)
	slowed.apply_slow(0.45, 2.0)
	check(not cc._accept(slowed), "cc: skips slowed targets")
	var fresh := PressureEnemy.new()
	track(fresh)
	check(cc._accept(fresh), "cc: unslowed target accepted")

	var m = Metrics.inst()
	var up_before: float = m.cc_uptime
	for i in range(60):
		e.slow_left = maxf(0.0, e.slow_left - 1.0 / 60.0)
		if e.slow_left > 0.0:
			m.add_cc_time(1.0 / 60.0)
	check(m.cc_uptime > up_before + 0.9 and m.cc_uptime <= up_before + 1.01,
			"metrics: cc uptime accumulates only while slowed")


func test_enemy_resistances() -> void:
	EnemyBase.stats = Stats.ensure()
	var mult_mg: float = EnemyBase.damage_multiplier(EnemyBase.Role.ARMORED,
			DamageEvent.Source.MG_TURRET, false)
	var mult_pilot: float = EnemyBase.damage_multiplier(EnemyBase.Role.ARMORED,
			DamageEvent.Source.PILOT_GUN, false)
	var mult_wp: float = EnemyBase.damage_multiplier(EnemyBase.Role.ARMORED,
			DamageEvent.Source.PILOT_GUN, true)
	check(mult_mg <= 0.15, "armored: MG shell resist near-zero (%.2f)" % mult_mg)
	check(mult_pilot > mult_mg, "armored: pilot body shots beat MG on shell")
	check(mult_wp >= 2.0, "armored: weakpoint hit heavily rewarded (%.2f)" % mult_wp)

	Metrics.reset_all()
	var p := PressureEnemy.new()
	track(p)
	p.max_hp = 100.0
	p.hp = 100.0
	p.take_damage(DamageEvent.new(40.0, DamageEvent.Source.MG_TURRET))
	check(p.hp == 60.0, "pressure: full damage from any source")
	check(Metrics.inst().damage_by_source.get("mg_turret", 0.0) == 40.0,
			"metrics: damage-by-source recorded at take_damage choke point")

	var armo := ArmoredEnemy.new()
	track(armo)
	armo.max_hp = 400.0
	armo.hp = 400.0
	armo.take_damage(DamageEvent.new(10.0, DamageEvent.Source.MG_TURRET))
	check(approx(armo.hp, 398.8, 0.05), "armored: MG shot absorbed by shell")


func test_metrics() -> void:
	Metrics.reset_all()
	var m = Metrics.inst()
	m.reset("test")
	m.log_kill("pilot_gun", "harasser")
	m.log_kill("pilot_gun", "armored")
	m.priority_kill()
	m.leak()
	m.supply_trip()
	check(m.kills_by_source.get("pilot_gun", 0) == 2, "metrics: kills aggregated by source")
	check(m.kills_of_role.get("armored", 0) == 1, "metrics: kills aggregated by role")
	check(m.priority_kills_by_pilot == 1 and m.leaks == 1 and m.supply_trips == 1,
			"metrics: counters increment")

	var path := "res://combat/tests/_tmp_dump.json"
	m.dump(path)
	var f := FileAccess.open(path, FileAccess.READ)
	var ok := f != null
	if ok:
		var parsed = JSON.parse_string(f.get_as_text())
		ok = parsed is Dictionary and parsed.has("kills_by_source") \
				and parsed["outcome"] != null
		f.close()
	check(ok, "metrics: dump writes parseable JSON with fields")
	if FileAccess.file_exists(path):
		DirAccess.remove_absolute(ProjectSettings.globalize_path(path))

class_name Session
extends RefCounted

## Parsed launch configuration (VS-1 runtime skeleton).
##
## Populated once by scenes/boot.gd from CLI user args (everything after "--"
## on the Godot command line). Everything else reads it; nobody writes it
## except apply()/reset(). Statics die with the process.

enum Mode { NORMAL, HOST, CLIENT, TEST, BENCHMARK }

const DEFAULT_SEED := 1
const DEFAULT_PORT := 7777

static var mode: Mode = Mode.NORMAL
static var seed_value: int = DEFAULT_SEED
## True when --seed=N was passed explicitly; gates the ADR-10 seed rule
## (CLI overrides kernel config meta.seed only when actually requested).
static var seed_explicit: bool = false
static var listen_port: int = DEFAULT_PORT
static var connect_address: String = ""
static var benchmark_name: String = ""
static var log_file: bool = false
static var log_categories: PackedStringArray = PackedStringArray()
## Client-only dev surface (wave step 2): graceful leave N seconds after the
## scene mounts; drives lifecycle/reconnect tests. 0 = disabled.
static var leave_after_sec: float = 0.0
## Этап 4 ladder surface: crowd size and auto-exit for any mode.
static var crowd_count: int = 64
static var quit_after_sec: float = 0.0
static var ladder_print: bool = false
## Этап 4 remainder: back the host crowd with the real CrowdSim runtime.
static var crowd_sim: bool = false
## VS-7 playable-operation surface. Implies real CrowdSim without benchmark prefill.
static var operation_mode: bool = false


static func reset() -> void:
	mode = Mode.NORMAL
	seed_value = DEFAULT_SEED
	listen_port = DEFAULT_PORT
	connect_address = ""
	benchmark_name = ""
	log_file = false
	log_categories = PackedStringArray()
	seed_explicit = false
	crowd_count = 64
	quit_after_sec = 0.0
	ladder_print = false
	crowd_sim = false
	operation_mode = false
	leave_after_sec = 0.0


## Grammar (all args optional):
##   --host                act as authoritative server
##   --connect=HOST[:PORT] join a host
##   --port=N              port for --host / --connect
##   --seed=N              deterministic seed (default 1; never time-based)
##   --test                headless test route (pairs with engine --headless -s)
##   --benchmark=NAME      named benchmark scene
##   --operation           run authored playable operation (implies real CrowdSim)
##   --log-file            force file sink (auto-on for TEST/BENCHMARK)
##   --log-cats=A,B        restrict log categories (default: all)
## Returns ERR_INVALID_PARAMETER (after printing why) on unknown args or
## mutually exclusive combinations.
static func apply(args: PackedStringArray) -> Error:
	reset()
	var exclusive := 0
	var wants_host := false
	var wants_client := false
	for arg in args:
		if arg == "--host":
			exclusive += 1
			wants_host = true
			mode = Mode.HOST
		elif arg.begins_with("--connect="):
			var spec := arg.get_slice("=", 1)
			var host := spec.get_slice(":", 0)
			if host.is_empty():
				return _bad(arg)
			connect_address = host
			if spec.contains(":"):
				var port_raw := spec.get_slice(":", 1)
				if not port_raw.is_valid_int():
					return _bad(arg)
				listen_port = int(port_raw)
			exclusive += 1
			wants_client = true
			mode = Mode.CLIENT
		elif arg == "--test":
			exclusive += 1
			mode = Mode.TEST
		elif arg.begins_with("--benchmark="):
			benchmark_name = arg.get_slice("=", 1)
			if benchmark_name.is_empty():
				return _bad(arg)
			exclusive += 1
			mode = Mode.BENCHMARK
		elif arg.begins_with("--seed="):
			var raw := arg.get_slice("=", 1)
			if not raw.is_valid_int():
				return _bad(arg)
			seed_value = int(raw)
			seed_explicit = true
		elif arg.begins_with("--port="):
			var port_raw := arg.get_slice("=", 1)
			if not port_raw.is_valid_int():
				return _bad(arg)
			listen_port = int(port_raw)
		elif arg.begins_with("--crowd-count="):
			var ccnt := arg.get_slice("=", 1)
			if not ccnt.is_valid_int():
				return _bad(arg)
			crowd_count = clampi(ccnt.to_int(), 1, 4096)
		elif arg == "--ladder-print":
			ladder_print = true
		elif arg == "--crowd-sim":
			crowd_sim = true
			ladder_print = true
		elif arg == "--operation":
			operation_mode = true
			crowd_sim = true
		elif arg.begins_with("--quit-after-sec="):
			var qsec := arg.get_slice("=", 1)
			if not qsec.is_valid_float():
				return _bad(arg)
			quit_after_sec = maxf(0.0, qsec.to_float())
		elif arg.begins_with("--leave-after="):
			var secs := arg.get_slice("=", 1)
			if not secs.is_valid_float():
				return _bad(arg)
			leave_after_sec = maxf(0.0, secs.to_float())
		elif arg == "--log-file":
			log_file = true
		elif arg.begins_with("--log-cats="):
			for cat in arg.get_slice("=", 1).split(",", false):
				log_categories.append(cat.strip_edges().to_upper())
		else:
			return _bad(arg)

	if exclusive > 1:
		printerr("Session: --host/--connect/--test/--benchmark are mutually exclusive")
		return ERR_INVALID_PARAMETER
	if wants_client and connect_address.is_empty():
		return ERR_INVALID_PARAMETER
	if operation_mode and not (wants_host or wants_client):
		printerr("Session: --operation requires --host or --connect")
		return ERR_INVALID_PARAMETER
	return OK


## Headful no-args developer Play/F5 promotion. The CLI grammar remains
## unchanged so tests/headless tools can still reason about NORMAL explicitly.
static func enable_local_operation() -> void:
	mode = Mode.HOST
	connect_address = ""
	operation_mode = true
	crowd_sim = true
	ladder_print = false


static func pure_crowd_ladder() -> bool:
	# Capacity/network benchmark must not be contaminated by synthetic pilot
	# damage. --operation is explicitly excluded: playable operation keeps the
	# real pilot combat path even though it also uses CrowdSim.
	return crowd_sim and ladder_print and not operation_mode


static func category_enabled(category: String) -> bool:
	return log_categories.is_empty() or log_categories.has(category)


static func _bad(arg: String) -> Error:
	printerr("Session: unknown or malformed argument '%s'" % arg)
	return ERR_INVALID_PARAMETER

class_name Version
extends RefCounted

## Build identity (VS-1). Sources of truth:
##   human version  -> application/config/version in project.godot
##   commit         -> game/VERSION.json (gitignored; falls back to "dev").
##                     Measured sessions (TEST/BENCHMARK) regenerate it at boot;
##                     manual regeneration: tools/make_version.gd.
##   engine + mode  -> queried live from the running binary

static var _cached_commit := ""


static func project_version() -> String:
	return ProjectSettings.get_setting("application/config/version", "unset")


static func commit() -> String:
	if _cached_commit != "":
		return _cached_commit
	_cached_commit = _read_commit()
	return _cached_commit


static func _read_commit() -> String:
	if not FileAccess.file_exists("res://VERSION.json"):
		return "dev"
	var f := FileAccess.open("res://VERSION.json", FileAccess.READ)
	if f == null:
		return "dev"
	var parsed: Variant = JSON.parse_string(f.get_as_text())
	if parsed is Dictionary and parsed.has("commit"):
		var dirty: bool = parsed.get("dirty", false)
		return String(parsed["commit"]) + ("*" if dirty else "")
	return "dev"


## Best-effort regeneration of VERSION.json from git (works where git works —
## editor/debug runs; silently degrades in exports). Returns a status string
## for logging: "written:<sha>[*]" | "no-git" | "write-failed".
static func regenerate() -> String:
	var repo := ProjectSettings.globalize_path("res://")
	var out: Array = []
	if OS.execute("git", ["-C", repo, "rev-parse", "--short", "HEAD"], out, true) != OK or out.is_empty():
		return "no-git"
	var commit := String(out[0]).strip_edges()
	var dirty := true
	var status: Array = []
	if OS.execute("git", ["-C", repo, "status", "--porcelain"], status, true) == OK and not status.is_empty():
		dirty = String(status[0]).strip_edges() != ""
	var f := FileAccess.open("res://VERSION.json", FileAccess.WRITE)
	if f == null:
		return "write-failed"
	f.store_string(JSON.stringify({
		"commit": commit,
		"dirty": dirty,
		"generated_utc": Time.get_datetime_string_from_system(true),
	}, "  ") + "\n")
	_cached_commit = ""
	return "written:%s%s" % [commit, "*" if dirty else ""]


static func engine_version() -> String:
	var v := Engine.get_version_info()
	return "%d.%d.%d.%s" % [v.major, v.minor, v.patch, v.status]


static func build_mode() -> String:
	if OS.has_feature("editor"):
		return "editor"
	return "debug" if OS.is_debug_build() else "release"


static func label() -> String:
	return "%s+%s godot-%s %s" % [project_version(), commit(), engine_version(), build_mode()]

extends RefCounted
class_name CrowdInterp
## VS2-T3: pure snapshot interpolation sampler (no node deps, headless-testable).
##
## Contract: returns {} unless both snapshots are non-empty and equally sized.
## target_ms = now - delay; t is clamped to [0,1] so rendering never runs
## ahead of the newest snap nor behind the oldest one. State arrays are carried
## through verbatim (dead enemies keep state=2 and are hidden downstream).


static func sample_interp(a: Dictionary, b: Dictionary, now_ms: int, delay_ms: float) -> Dictionary:
	var n: int = a.uid.size()
	if n == 0 or b.uid.size() != n:
		return {}
	var target_ms := float(now_ms) - delay_ms
	var span := maxf(1.0, float(b.recv_ms - a.recv_ms))
	var t: float = clampf((target_ms - float(a.recv_ms)) / span, 0.0, 1.0)
	var ix := PackedFloat32Array(); ix.resize(n)
	var iz := PackedFloat32Array(); iz.resize(n)
	for i in n:
		ix[i] = lerpf(a.x[i], b.x[i], t)
		iz[i] = lerpf(a.z[i], b.z[i], t)
	return {
		"x": ix, "z": iz, "state": a.state,
		"flags": a.get("flags", PackedByteArray()),
		"lane": a.get("lane", PackedByteArray()),
	}

class_name CrowdSim
extends RefCounted

## HARVEST pressure-enemy simulation. Pure data, zero Nodes per enemy.
##
## Layout: structure-of-arrays over Packed*Array with dense slots +
## free-list. Chosen over Array[Dictionary] after measurement
## (see benchmarks/micro_layout.gd results).
##
## Enemy fields:
##   px, pz   float32  position (meters, XZ plane)
##   vx, vz   float32  velocity
##   hp       float32
##   speed    float32  personal max speed
##   uid      int32    stable identity across swaps (for snapshots)
##   state    uint8    CrowdSim.ST_MOVE / ST_ATTACK / ST_DEAD
##   flags    uint8    F_AGGRO
##   lane     uint8    spawn lane index
##   phase    float32  animation phase (renderer)

const ST_MOVE := 0
const ST_ATTACK := 1
const ST_DEAD := 2

const F_AGGRO := 1
const F_ROLE_ARMORED := 1 << 1
const F_ROLE_HARASSER := 1 << 2
const F_HARASSER_WARNED := 1 << 3
const F_ROLE_MASK := F_ROLE_ARMORED | F_ROLE_HARASSER

const ROLE_PRESSURE := 0
const ROLE_ARMORED := 1
const ROLE_HARASSER := 2

# tuning
const SPEED_BASE := 3.2
const SPEED_VAR := 0.5
const ACCEL := 8.0
const HP0 := 100.0
const SEP_R := 0.6
const SEP_R2 := SEP_R * SEP_R
const SEP_STRENGTH := 4.5
const CORE_RADIUS := 2.5
const ENGAGE_R := CORE_RADIUS + 3.0
const ATTACK_DPS := 20.0
const MAX_SPEED_OVER := 1.35   # clamp = speed * this (push overshoot)
const HARASSER_ATTACK_R := 2.2
const NO_INFRA_TARGET := 255

const DEFAULT_LANE_CELLS := [Vector2i(2, 13), Vector2i(2, 40), Vector2i(2, 67)]
const DEFAULT_CORE_CELL := Vector2i(63, 40)

var field: FlowField
var _lane_cells: Array[Vector2i] = []
var _core_cell := DEFAULT_CORE_CELL

# SoA storage
var cap: int
var active: int = 0
var px := PackedFloat32Array()
var pz := PackedFloat32Array()
var vx := PackedFloat32Array()
var vz := PackedFloat32Array()
var hp := PackedFloat32Array()
var max_hp := PackedFloat32Array()
var speed := PackedFloat32Array()
var slow_mul := PackedFloat32Array()
var slow_left := PackedFloat32Array()
var attack_cd := PackedFloat32Array()
var phase := PackedFloat32Array()
var uid := PackedInt32Array()
var state := PackedByteArray()
var flags := PackedByteArray()
var lane := PackedByteArray()
var batch_token := PackedInt32Array()
var harasser_target := PackedByteArray()

var _next_uid: int = 1
var _uid_slot := {}                  # uid -> dense slot index (combat API)

# wave spawning
var pending_spawn: int = 0
var spawn_rate := 0.0                # enemies per second
var _spawn_carry := 0.0
## Mission-driven trickle batches: {remaining, lane, rate, carry}.
## Kept separate from begin_wave() so the VS-4 benchmark surface remains intact.
var spawn_batches: Array = []
var role_tuning: Dictionary = {}
var infrastructure_targets: Array = []
var infrastructure_warnings: Array = []
var infrastructure_strikes: Array = []

# core / aggro
var core_pos := Vector2.ZERO
var core_hp := 10000.0
var aggro_cap := 24
var aggro_active := 0

# spawned/died event tracking for snapshot codec
var spawned_uids: Array[int] = []
var died_uids: Array[int] = []

# rng
var rng := RandomNumberGenerator.new()

# spatial hash (uniform grid, counting sort, preallocated)
const HASH_CELL := 1.2
var _hw: int
var _hh: int
var _hstarts := PackedInt32Array()
var _horder := PackedInt32Array()
var _hbucket := PackedInt32Array()
var _hcursor := PackedInt32Array()

# stats (cumulative usec since last take_stats)
var us_flow := 0
var us_spawn := 0
var us_hash := 0
var us_agents := 0


func _init(p_cap: int = 512, p_seed: int = 1337,
		p_w: int = FlowField.DEFAULT_W, p_h: int = FlowField.DEFAULT_H,
		p_cell: float = FlowField.DEFAULT_CELL) -> void:
	cap = p_cap
	rng.seed = p_seed
	field = FlowField.make_td_arena(p_w, p_h, p_cell)
	_lane_cells.clear()
	for lane_cell in DEFAULT_LANE_CELLS:
		_lane_cells.append(lane_cell)
	_core_cell = DEFAULT_CORE_CELL
	core_pos = field.cell_center(_core_cell.x, _core_cell.y)
	px.resize(cap)
	pz.resize(cap)
	vx.resize(cap)
	vz.resize(cap)
	hp.resize(cap)
	max_hp.resize(cap)
	speed.resize(cap)
	slow_mul.resize(cap)
	slow_left.resize(cap)
	attack_cd.resize(cap)
	phase.resize(cap)
	uid.resize(cap)
	state.resize(cap)
	flags.resize(cap)
	lane.resize(cap)
	batch_token.resize(cap)
	harasser_target.resize(cap)
	harasser_target.fill(NO_INFRA_TARGET)
	_hbucket.resize(cap)
	_resize_hash_buffers()
	rebuild_field()


func configure_navigation(p_field: FlowField, p_core_cell: Vector2i,
		p_lane_cells: Array[Vector2i]) -> void:
	# Called before spawning for production operation setup, and again on
	# authored topology events such as Lane-C breach. Entity coordinates stay
	# in field-space, so reconfiguration does not invalidate active slots.
	field = p_field
	_core_cell = p_core_cell
	_lane_cells.clear()
	for lane_cell in p_lane_cells:
		_lane_cells.append(lane_cell)
	core_pos = field.cell_center(_core_cell.x, _core_cell.y)
	_resize_hash_buffers()
	rebuild_field()


func _resize_hash_buffers() -> void:
	_hw = maxi(1, int(ceil(float(field.w) * field.cell / HASH_CELL)))
	_hh = maxi(1, int(ceil(float(field.h) * field.cell / HASH_CELL)))
	var hash_slots := _hw * _hh + 1
	_hstarts.resize(hash_slots)
	_hcursor.resize(hash_slots)
	_hbucket.resize(cap)
	_horder.resize(cap)


func hash_buffers_valid() -> bool:
	var expected_hw := maxi(1, int(ceil(float(field.w) * field.cell / HASH_CELL)))
	var expected_hh := maxi(1, int(ceil(float(field.h) * field.cell / HASH_CELL)))
	var expected_slots := expected_hw * expected_hh + 1
	return _hw == expected_hw and _hh == expected_hh \
		and _hstarts.size() == expected_slots and _hcursor.size() == expected_slots \
		and _hbucket.size() >= cap and _horder.size() >= cap


func _ensure_hash_buffers() -> void:
	if not hash_buffers_valid():
		print("[CROWD_HASH_REPAIR] active=%d cap=%d hw=%d hh=%d starts=%d cursor=%d bucket=%d order=%d" % [
			active, cap, _hw, _hh, _hstarts.size(), _hcursor.size(),
			_hbucket.size(), _horder.size()
		])
		_resize_hash_buffers()


## Rebuild flow field if dirty. Returns ms spent (0 if clean).
func rebuild_field() -> float:
	var goals_x: Array[int] = [_core_cell.x]
	var goals_y: Array[int] = [_core_cell.y]
	var ms := field.rebuild(goals_x, goals_y)
	us_flow += int(ms * 1000.0)
	return ms


func set_runtime_blocker(x: float, z: float, blocked: bool) -> void:
	field.set_block_cell(field.world_to_cx(x), field.world_to_cy(z), 1 if blocked else 0)


func configure_role_tuning(p_roles: Dictionary) -> void:
	role_tuning = p_roles.duplicate(true)


func configure_infrastructure_targets(targets: Array) -> void:
	infrastructure_targets = targets.duplicate(true)
	for i in range(infrastructure_targets.size()):
		var target: Dictionary = infrastructure_targets[i]
		target["active"] = bool(target.get("active", true))
		infrastructure_targets[i] = target
	for i in range(active):
		if role_of_slot(i) == ROLE_HARASSER:
			harasser_target[i] = NO_INFRA_TARGET
			flags[i] &= ~F_HARASSER_WARNED


func disable_infrastructure_target(target_id: String) -> void:
	for ti in range(infrastructure_targets.size()):
		var target: Dictionary = infrastructure_targets[ti]
		if str(target.get("id", "")) == target_id:
			target["active"] = false
			infrastructure_targets[ti] = target
			for i in range(active):
				if int(harasser_target[i]) == ti:
					harasser_target[i] = NO_INFRA_TARGET
					flags[i] &= ~F_HARASSER_WARNED
			return


func take_infrastructure_warnings() -> Array:
	var out := infrastructure_warnings.duplicate(true)
	infrastructure_warnings.clear()
	return out


func take_infrastructure_strikes() -> Array:
	var out := infrastructure_strikes.duplicate(true)
	infrastructure_strikes.clear()
	return out


static func role_id(role_name: String) -> int:
	match role_name.to_upper():
		"ARMORED":
			return ROLE_ARMORED
		"HARASSER":
			return ROLE_HARASSER
		_:
			return ROLE_PRESSURE


static func role_name(role_value: int) -> String:
	return ["PRESSURE", "ARMORED", "HARASSER"][clampi(role_value, 0, 2)]


func role_of_slot(i: int) -> int:
	if i < 0 or i >= active:
		return ROLE_PRESSURE
	if (flags[i] & F_ROLE_ARMORED) != 0:
		return ROLE_ARMORED
	if (flags[i] & F_ROLE_HARASSER) != 0:
		return ROLE_HARASSER
	return ROLE_PRESSURE


func begin_wave(total: int, duration_s: float) -> void:
	pending_spawn = total
	spawn_rate = float(total) / maxf(duration_s, 0.001)


func queue_batch(total: int, lane_index: int, duration_s: float = 2.0,
		role_value: int = ROLE_PRESSURE, token: int = 0) -> void:
	if total <= 0:
		return
	spawn_batches.append({
		"remaining": total,
		"lane": lane_index,
		"role": role_value,
		"token": token,
		"rate": float(total) / maxf(duration_s, 0.05),
		"carry": 0.0,
	})


func spawn_idle() -> bool:
	return pending_spawn <= 0 and spawn_batches.is_empty()


func batch_present(token: int) -> bool:
	if token <= 0:
		return false
	for batch in spawn_batches:
		if int(batch.get("token", 0)) == token and int(batch.get("remaining", 0)) > 0:
			return true
	for i in range(active):
		if batch_token[i] == token:
			return true
	return false


func spawn_one(l: int = -1) -> bool:
	if pending_spawn <= 0:
		return false
	pending_spawn -= 1
	return _spawn_at_lane(l, ROLE_PRESSURE, 0)


func _spawn_at_lane(l: int = -1, role_value: int = ROLE_PRESSURE,
		token: int = 0) -> bool:
	if active >= cap or _lane_cells.is_empty():
		return false
	var ln := l
	if ln < 0:
		ln = rng.randi_range(0, _lane_cells.size() - 1)
	ln = clampi(ln, 0, _lane_cells.size() - 1)
	var i := active
	active += 1
	var c: Vector2i = _lane_cells[ln]
	var base := field.cell_center(c.x, c.y)
	px[i] = base.x + rng.randf_range(-1.5, 1.5)
	pz[i] = base.y + rng.randf_range(-1.5, 1.5)
	vx[i] = 0.0
	vz[i] = 0.0
	var role_key := role_name(role_value)
	var tuning: Dictionary = role_tuning.get(role_key, {})
	max_hp[i] = float(tuning.get("hp_per_unit", HP0))
	hp[i] = max_hp[i]
	match role_value:
		ROLE_ARMORED:
			speed[i] = 1.6 + rng.randf_range(-0.15, 0.15)
		ROLE_HARASSER:
			speed[i] = 5.0 + rng.randf_range(-0.35, 0.35)
		_:
			speed[i] = SPEED_BASE + rng.randf_range(-SPEED_VAR, SPEED_VAR)
	slow_mul[i] = 1.0
	slow_left[i] = 0.0
	attack_cd[i] = 0.0
	phase[i] = rng.randf()
	uid[i] = _next_uid
	_next_uid += 1
	state[i] = ST_MOVE
	flags[i] = 0
	batch_token[i] = token
	harasser_target[i] = NO_INFRA_TARGET
	if role_value == ROLE_ARMORED:
		flags[i] |= F_ROLE_ARMORED
	elif role_value == ROLE_HARASSER:
		flags[i] |= F_ROLE_HARASSER
		harasser_target[i] = _pick_infrastructure_target()
	lane[i] = ln
	_uid_slot[uid[i]] = i
	spawned_uids.append(uid[i])
	return true


## Combat entry point. Returns true if this hit killed the target.
## Unknown/stale uids are a safe no-op returning false — callers can never
## touch slots directly, so swap-remove cannot be raced from outside.
func damage(p_uid: int, amt: float, source_kind: String = "other",
		weakpoint: bool = false) -> bool:
	var i := slot_of_uid(p_uid)
	if i < 0:
		return false
	var effective := amt
	if role_of_slot(i) == ROLE_ARMORED:
		if weakpoint:
			effective *= 2.5
		else:
			match source_kind:
				"mg":
					effective *= 0.12
				"cc":
					effective *= 0.5
				"pilot":
					effective *= 0.35
				"mech_rotary":
					effective *= 0.5
				"mech_rocket":
					effective *= 2.0
	hp[i] -= effective
	if hp[i] <= 0.0:
		kill(i)
		return true
	return false


func slot_of_uid(p_uid: int) -> int:
	return int(_uid_slot.get(p_uid, -1))


func get_hp(p_uid: int) -> float:
	var i := slot_of_uid(p_uid)
	return hp[i] if i >= 0 else -1.0


func hp_wire_percent(i: int) -> float:
	if i < 0 or i >= active:
		return 0.0
	return clampf(hp[i] / maxf(max_hp[i], 0.001) * 100.0, 0.0, 100.0)


func apply_slow(p_uid: int, factor: float, duration: float) -> bool:
	var i := slot_of_uid(p_uid)
	if i < 0:
		return false
	slow_mul[i] = minf(slow_mul[i], clampf(factor, 0.1, 1.0))
	slow_left[i] = maxf(slow_left[i], maxf(duration, 0.0))
	return true


func is_slowed_slot(i: int) -> bool:
	return i >= 0 and i < active and slow_left[i] > 0.0


func _pick_infrastructure_target() -> int:
	var choices: Array[int] = []
	for ti in range(infrastructure_targets.size()):
		if bool(infrastructure_targets[ti].get("active", true)):
			choices.append(ti)
	if choices.is_empty():
		return NO_INFRA_TARGET
	return choices[rng.randi_range(0, choices.size() - 1)]


func _ensure_harasser_target(i: int) -> int:
	var ti := int(harasser_target[i])
	if ti >= 0 and ti < infrastructure_targets.size() \
			and bool(infrastructure_targets[ti].get("active", true)):
		return ti
	ti = _pick_infrastructure_target()
	harasser_target[i] = ti
	flags[i] &= ~F_HARASSER_WARNED
	return ti


func kill(i: int) -> void:
	if i < 0 or i >= active or state[i] == ST_DEAD:
		return
	died_uids.append(uid[i])
	if state[i] == ST_ATTACK and (flags[i] & F_AGGRO) != 0:
		aggro_active = maxi(0, aggro_active - 1)
	# true swap-remove: move last alive into slot i, shrink active
	var last := active - 1
	if i != last:
		px[i] = px[last]
		pz[i] = pz[last]
		vx[i] = vx[last]
		vz[i] = vz[last]
		hp[i] = hp[last]
		max_hp[i] = max_hp[last]
		speed[i] = speed[last]
		slow_mul[i] = slow_mul[last]
		slow_left[i] = slow_left[last]
		attack_cd[i] = attack_cd[last]
		phase[i] = phase[last]
		uid[i] = uid[last]
		state[i] = state[last]
		flags[i] = flags[last]
		lane[i] = lane[last]
		batch_token[i] = batch_token[last]
		harasser_target[i] = harasser_target[last]
		_uid_slot[uid[i]] = i      # moved enemy now lives at slot i
	_uid_slot.erase(died_uids[died_uids.size() - 1])
	active -= 1


func take_stats() -> Dictionary:
	var d := {
		"us_flow": us_flow, "us_spawn": us_spawn, "us_hash": us_hash,
		"us_agents": us_agents, "active": active,
		"core_hp": core_hp, "aggro_active": aggro_active,
	}
	us_flow = 0
	us_spawn = 0
	us_hash = 0
	us_agents = 0
	return d


func _rebuild_hash() -> void:
	var t2 := Time.get_ticks_usec()
	_ensure_hash_buffers()
	var buckets := _hw * _hh
	_hstarts.fill(0)
	var inv := 1.0 / HASH_CELL
	for i in range(active):
		var bx := int(px[i] * inv)
		var bz := int(pz[i] * inv)
		if bx < 0: bx = 0
		elif bx >= _hw: bx = _hw - 1
		if bz < 0: bz = 0
		elif bz >= _hh: bz = _hh - 1
		var b := bz * _hw + bx
		_hbucket[i] = b
		_hstarts[b + 1] += 1
	for k in range(buckets):
		_hstarts[k + 1] += _hstarts[k]
	for k in range(buckets + 1):
		_hcursor[k] = _hstarts[k]
	for i in range(active):
		var b2 := _hbucket[i]
		_horder[_hcursor[b2]] = i
		_hcursor[b2] += 1
	us_hash += Time.get_ticks_usec() - t2


## One fixed-step tick. dt must stay constant for determinism (e.g. 1/60).
func step(dt: float) -> void:
	var t0 := Time.get_ticks_usec()

	if field.dirty:
		rebuild_field()
	var t1 := Time.get_ticks_usec()
	us_flow += t1 - t0

	# --- trickle spawn: legacy benchmark wave + mission-driven batches ---
	if pending_spawn > 0:
		_spawn_carry += spawn_rate * dt
		var n := int(_spawn_carry)
		_spawn_carry -= float(n)
		for k in range(n):
			if not spawn_one():
				break

	for bi in range(spawn_batches.size() - 1, -1, -1):
		var batch: Dictionary = spawn_batches[bi]
		batch.carry = float(batch.carry) + float(batch.rate) * dt
		var requested := mini(int(batch.carry), int(batch.remaining))
		var spawned := 0
		for k in range(requested):
			if not _spawn_at_lane(
					int(batch.lane),
					int(batch.get("role", ROLE_PRESSURE)),
					int(batch.get("token", 0))):
				break
			spawned += 1
		batch.remaining = int(batch.remaining) - spawned
		batch.carry = float(batch.carry) - float(spawned)
		if int(batch.remaining) <= 0:
			spawn_batches.remove_at(bi)
		else:
			spawn_batches[bi] = batch
	us_spawn += Time.get_ticks_usec() - t1

	# --- spatial hash rebuild (counting sort, zero allocs after warmup) ---
	_rebuild_hash()

	# --- agents: separation + steering + integrate ---
	var t3 := Time.get_ticks_usec()
	var inv := 1.0 / HASH_CELL
	for i in range(active):
		var st := state[i]
		if st == ST_DEAD:
			continue
		var x := px[i]
		var z := pz[i]
		if slow_left[i] > 0.0:
			slow_left[i] = maxf(0.0, slow_left[i] - dt)
			if slow_left[i] <= 0.0:
				slow_mul[i] = 1.0
		var move_speed := speed[i] * slow_mul[i]

		# separation from 3x3 hash neighborhood
		var sx := 0.0
		var sz := 0.0
		var bx := int(x * inv)
		var bz := int(z * inv)
		if bx < 0: bx = 0
		elif bx >= _hw: bx = _hw - 1
		if bz < 0: bz = 0
		elif bz >= _hh: bz = _hh - 1
		var by0 := bz - 1 if bz > 0 else 0
		var by1 := bz + 1 if bz < _hh - 1 else bz
		var bx0 := bx - 1 if bx > 0 else 0
		var bx1 := bx + 1 if bx < _hw - 1 else bx
		for yy in range(by0, by1 + 1):
			var rowb := yy * _hw
			for xx in range(bx0, bx1 + 1):
				var b := rowb + xx
				var j0 := _hstarts[b]
				var j1 := _hstarts[b + 1]
				for k in range(j0, j1):
					var j := _horder[k]
					if j == i:
						continue
					var dx := x - px[j]
					var dz := z - pz[j]
					var d2 := dx * dx + dz * dz
					if d2 < SEP_R2 and d2 > 0.000001:
						var w := (SEP_R2 - d2) / SEP_R2
						var invd := w / sqrt(d2)
						sx += dx * invd
						sz += dz * invd

		# desired direction. Harassers are flying infrastructure attackers.
		var role_value := role_of_slot(i)
		var flying_harasser := false
		var des := Vector2.ZERO
		if role_value == ROLE_HARASSER:
			var target_i := _ensure_harasser_target(i)
			if target_i != NO_INFRA_TARGET:
				flying_harasser = true
				var target: Dictionary = infrastructure_targets[target_i]
				var target_pos: Vector2 = target.get("pos", core_pos)
				var to_target := target_pos - Vector2(x, z)
				var dist_target := to_target.length()
				if dist_target <= HARASSER_ATTACK_R:
					state[i] = ST_ATTACK
					flags[i] = flags[i] & ~F_AGGRO
					if (flags[i] & F_HARASSER_WARNED) == 0:
						flags[i] |= F_HARASSER_WARNED
						attack_cd[i] = maxf(attack_cd[i], 0.75)
						infrastructure_warnings.append({
							"target_id": str(target.get("id", "")),
							"uid": uid[i],
						})
					attack_cd[i] -= dt
					if attack_cd[i] <= 0.0:
						var tuning: Dictionary = role_tuning.get("HARASSER", {})
						infrastructure_strikes.append({
							"target_id": str(target.get("id", "")),
							"damage": float(tuning.get("infra_damage", 12.0)),
							"uid": uid[i],
						})
						attack_cd[i] = float(tuning.get("infra_interval_s", 2.2))
				else:
					flags[i] &= ~F_HARASSER_WARNED
					state[i] = ST_MOVE
					attack_cd[i] = maxf(0.0, attack_cd[i] - dt)
					des = to_target.normalized() * move_speed

		if not flying_harasser:
			var dvec := Vector2(core_pos.x - x, core_pos.y - z)
			var dist_core := dvec.length()
			if st == ST_ATTACK:
				des = Vector2.ZERO
				if dist_core > ENGAGE_R + 1.0:
					state[i] = ST_MOVE
					st = ST_MOVE
					if (flags[i] & F_AGGRO) != 0:
						flags[i] = flags[i] & ~F_AGGRO
						aggro_active = maxi(0, aggro_active - 1)
				else:
					core_hp -= _attack_dps(i) * dt
			else:
				var fd := field.dir[field.world_to_cy(z) * field.w + field.world_to_cx(x)]
				if dist_core < ENGAGE_R and fd == Vector2.ZERO:
					fd = dvec.normalized()
				des = fd * move_speed
				if dist_core < CORE_RADIUS + 0.8:
					if aggro_active < aggro_cap and st == ST_MOVE:
						state[i] = ST_ATTACK
						flags[i] |= F_AGGRO
						aggro_active += 1
						des = Vector2.ZERO
						core_hp -= _attack_dps(i) * dt
					else:
						var radial := dvec.normalized()
						des = Vector2(-radial.y, radial.x) * move_speed * 0.7 - radial * move_speed * 0.15

		# integrate: vel lerp toward desired + separation push
		var tvx := des.x + sx * SEP_STRENGTH
		var tvz := des.y + sz * SEP_STRENGTH
		var a := minf(ACCEL * dt, 1.0)
		var nvx := vx[i] + (tvx - vx[i]) * a
		var nvz := vz[i] + (tvz - vz[i]) * a
		var sp_max := move_speed * MAX_SPEED_OVER
		var v2 := nvx * nvx + nvz * nvz
		if v2 > sp_max * sp_max:
			var s := sp_max / sqrt(v2)
			nvx *= s
			nvz *= s
		# Ground enemies slide around authored blockers; Harasser flies.
		var nx := x + nvx * dt
		var nz := z + nvz * dt
		if not flying_harasser and field.cell_blocked_at(nx, nz):
			if not field.cell_blocked_at(nx, z):
				nz = z
				nvz = 0.0
			elif not field.cell_blocked_at(x, nz):
				nx = x
				nvx = 0.0
			else:
				nx = x
				nz = z
				nvx = 0.0
				nvz = 0.0
		px[i] = nx
		pz[i] = nz
		vx[i] = nvx
		vz[i] = nvz
		phase[i] = fmod(phase[i] + dt, 1.0)
	us_agents += Time.get_ticks_usec() - t3


func _attack_dps(i: int) -> float:
	var role_key := role_name(role_of_slot(i))
	var tuning: Dictionary = role_tuning.get(role_key, {})
	return float(tuning.get("leak_dps", ATTACK_DPS))


## Cheap determinism checksum: quantized position sums + active count.
func checksum() -> int:
	var s := active * 1000003
	for i in range(active):
		s += int(px[i] * 64.0) + int(pz[i] * 64.0) * 7919 + uid[i] * 104729
	return s


func memory_bytes() -> int:
	var f4 := px.size() + pz.size() + vx.size() + vz.size() + hp.size() \
		+ max_hp.size() + speed.size() + slow_mul.size() + slow_left.size() \
		+ attack_cd.size() + phase.size() + uid.size() + batch_token.size()
	return (
		f4 * 4
		+ state.size() + flags.size() + lane.size() + harasser_target.size()
		+ (_hstarts.size() + _hcursor.size()) * 4 + _horder.size() * 4
		+ field.memory_bytes()
	)

extends Node3D
class_name CrowdStream

signal infrastructure_warning(target_id: String, enemy_uid: int)
signal infrastructure_strike(target_id: String, damage: float, enemy_uid: int)
## Host-authoritative packed enemy crowd, wire format = HSNP v1 (uid-addressed).
##
## VS2-T5: single crowd codec project-wide (EnemySnapshotCodec); core_hp moved
## out of the snapshot to a reliable synced var (CoreObject StateSynchronizer).
## VS2-T2: client render buffer is sized by the DECODED snapshot, so host/client
## enemy-count config mismatches cannot cause index errors; hostile counts are
## clamped in the codec. Dead enemies use state 2 per CrowdSim canon.
## VS2-T3: interpolation respects the 100 ms buffer (no dead condition) and
## carries full per-snapshot state arrays (dead enemies are hidden).

const SNAPSHOT_EVERY_TICKS := 2   # 30 Hz tick -> 15 Hz snapshots
const LADDER_FILL_SEC := 8.0       # pure stress ladder reaches target before measurement
const INTERP_DELAY_MS := 100.0
const ARENA_SIZE_M := 48.0

@export var count := 64

# Host sim arrays (SoA), uid-addressed on the wire
var _uid := PackedInt32Array()
var _xs := PackedFloat32Array()
var _zs := PackedFloat32Array()
var _hp := PackedFloat32Array()
var _state := PackedInt32Array()
var _flags := PackedInt32Array()
var _lane := PackedInt32Array()
var _respawn_t := PackedFloat32Array()
var _next_uid := 0
var _spawned_uids := PackedInt32Array()
var _died_uids := PackedInt32Array()

var _tick := 0
var core: CoreObject = null   # authoritative core HP lives there (VS2-T5)

# client-side: last decoded snapshot + interp history
var _snaps := []   # [{recv_ms:int, uid,x,z,state,hp (decoded arrays)}]

var _role_mms: Dictionary = {}
var _armored_weak_mm: MultiMesh = null
var _metrics = null
var ladder_print := false
var _last_snap_bytes := 0
## Этап 4 remainder: when enabled, the HOST simulation is a real CrowdSim
## (flow field + damage(uid)); snapshots are encoded straight from SoA.
var sim_mode := false
var sim: CrowdSim = null
var _sim_acc := 0.0
var _last_core_hp := -1.0
var _core_damage_debt := 0.0
var _lane_c_open := false
var _rendered_count := 0


func setup(p_count: int, p_metrics) -> void:
	count = p_count
	_metrics = p_metrics


## Этап 4 remainder: back the host crowd with CrowdSim (flow-field nav,
## trickle spawn, damage(uid)). Client decode/interp path is unchanged.
func enable_sim(seed_v: int, initial_fill: bool = true) -> void:
	sim_mode = true
	var field := OperationNav.build_field(false)
	sim = CrowdSim.new(
		count,
		seed_v,
		OperationLayout.GRID_W,
		OperationLayout.GRID_H,
		OperationLayout.CROWD_CELL
	)
	sim.configure_navigation(field, OperationNav.core_cell(), OperationNav.lane_cells(false))
	_last_core_hp = sim.core_hp
	_core_damage_debt = 0.0
	if initial_fill:
		# Capacity ladder measures steady-state crowd/network behavior, not
		# authored operation spawn cadence. Keep the fill window bounded so
		# 64/96/128/150 reach their requested population before timeout.
		sim.begin_wave(count, LADDER_FILL_SEC)


func set_lane_c_open(open: bool) -> void:
	if not sim_mode or sim == null or open == _lane_c_open:
		return
	_lane_c_open = open
	sim.configure_navigation(
		OperationNav.build_field(open),
		OperationNav.core_cell(),
		OperationNav.lane_cells(open)
	)


func configure_role_tuning(roles: Dictionary) -> void:
	if sim_mode and sim != null:
		sim.configure_role_tuning(roles)


func configure_infrastructure_targets(world_targets: Array) -> void:
	if not sim_mode or sim == null:
		return
	var half := sim.field.size_m * 0.5
	var field_targets: Array = []
	for target in world_targets:
		var pos: Vector3 = target.get("pos", Vector3.ZERO)
		field_targets.append({
			"id": str(target.get("id", "")),
			"pos": Vector2(pos.x + half, pos.z + half),
			"active": bool(target.get("active", true)),
		})
	sim.configure_infrastructure_targets(field_targets)


func disable_infrastructure_target(target_id: String) -> void:
	if sim_mode and sim != null:
		sim.disable_infrastructure_target(target_id)


func queue_spawn_intent(lane_id: String, role_name: String, amount: int,
		aggression: float = 1.0, batch_token: int = 0) -> bool:
	if not sim_mode or sim == null or amount <= 0:
		return false
	var lane_index: int = int({"A": 0, "B": 1, "C": 2}.get(lane_id, -1))
	if lane_index < 0:
		return false
	if lane_id == "C" and not _lane_c_open:
		set_lane_c_open(true)
	var duration := clampf(2.5 / maxf(aggression, 0.25), 0.5, 4.0)
	sim.queue_batch(amount, lane_index, duration, CrowdSim.role_id(role_name), batch_token)
	return true


func batch_present(batch_token: int) -> bool:
	return sim_mode and sim != null and sim.batch_present(batch_token)


func simulation_idle() -> bool:
	if sim_mode and sim != null:
		return sim.active == 0 and sim.spawn_idle()
	return false


func _ingest_snapshot(bytes: PackedByteArray, inbound: bool = true) -> void:
	var snap := EnemySnapshotCodec.decode(bytes)
	if snap.is_empty():
		if _metrics:
			_metrics.count("crowd_snap_rejected")
		return
	if _metrics and inbound:
		_metrics.add_bytes("crowd_in", bytes.size())
		_metrics.count("crowd_snaps_recv")
	var half: float = snap.arena_size_m * 0.5
	var wx: PackedFloat32Array = snap.x
	var wz: PackedFloat32Array = snap.z
	for i in wx.size():
		wx[i] = wx[i] - half
		wz[i] = wz[i] - half
	_snaps.append({
		"recv_ms": Time.get_ticks_msec(), "uid": snap.uid,
		"x": wx, "z": wz, "state": snap.state, "hp": snap.hp,
		"flags": snap.flags, "lane": snap.lane,
	})
	while _snaps.size() > 6:
		_snaps.pop_front()


func _ready() -> void:
	_build_view()
	if multiplayer.is_server() and not sim_mode:
		_init_enemies()


func _build_view() -> void:
	# Fixed batched role buckets: distinct silhouettes without Node-per-enemy.
	_role_mms.clear()

	var pressure := CapsuleMesh.new()
	pressure.radius = 0.32
	pressure.height = 1.05
	_role_mms["PRESSURE"] = _create_role_bucket(
		"CrowdPressure", pressure, Color(0.78, 0.20, 0.12), false)

	var armored := BoxMesh.new()
	armored.size = Vector3(1.15, 1.55, 0.92)
	_role_mms["ARMORED"] = _create_role_bucket(
		"CrowdArmored", armored, Color(0.10, 0.11, 0.12), false)

	var harasser := CylinderMesh.new()
	harasser.top_radius = 0.62
	harasser.bottom_radius = 0.62
	harasser.height = 0.28
	harasser.radial_segments = 6
	_role_mms["HARASSER"] = _create_role_bucket(
		"CrowdHarasser", harasser, Color(0.52, 0.22, 0.62), true)

	var weak := SphereMesh.new()
	weak.radius = 0.20
	weak.height = 0.40
	_armored_weak_mm = _create_role_bucket(
		"ArmoredWeakpoints", weak, Color(1.0, 0.55, 0.12), true)


func _create_role_bucket(name_v: String, mesh: Mesh, color: Color,
		emissive: bool) -> MultiMesh:
	var inst := MultiMeshInstance3D.new()
	inst.name = name_v
	var mm := MultiMesh.new()
	mm.transform_format = MultiMesh.TRANSFORM_3D
	mm.mesh = mesh
	mm.instance_count = maxi(1, count)
	mm.visible_instance_count = 0
	var mat := StandardMaterial3D.new()
	mat.albedo_color = color
	mat.roughness = 0.78
	if emissive:
		mat.emission_enabled = true
		mat.emission = color
		mat.emission_energy_multiplier = 1.7
	inst.material_override = mat
	inst.multimesh = mm
	add_child(inst)
	return mm


func _init_enemies() -> void:
	_uid.resize(count)
	_xs.resize(count)
	_zs.resize(count)
	_hp.resize(count)
	_state.resize(count)
	_flags.resize(count)
	_lane.resize(count)
	_respawn_t.resize(count)
	for i in count:
		_uid[i] = _next_uid
		_next_uid += 1
		var ang := TAU * float(i) / float(count)
		_xs[i] = cos(ang) * 16.0
		_zs[i] = sin(ang) * 16.0
		_hp[i] = 100.0
		_state[i] = EnemySnapshotCodec.ST_MOVE
		_flags[i] = 0
		_lane[i] = 0


func enemy_count() -> int:
	if multiplayer.is_server() and sim_mode and sim != null:
		return sim.active
	return count if multiplayer.is_server() else _decoded_count()


func _decoded_count() -> int:
	return 0 if _snaps.is_empty() else _snaps[-1].uid.size()


## Host-only simulation step, called from boot on NetworkTime.after_tick.
func host_step(dt: float) -> void:
	if sim_mode:
		# Этап 4 remainder: real CrowdSim drives the host crowd. Fixed 60 Hz
		# sim steps accumulated from the net tick delta; snapshots encoded
		# straight from SoA; core erosion bridged to the CoreObject.
		_sim_acc += dt
		var sdt := 1.0 / 60.0
		while _sim_acc >= sdt:
			sim.step(sdt)
			_sim_acc -= sdt
		_tick += 1
		var bytes := EnemySnapshotCodec.encode(sim, _tick)
		_last_snap_bytes = bytes.size()
		_ingest_snapshot(bytes, false)
		crowd_snapshot.rpc(bytes)
		EnemySnapshotCodec.clear_events(sim)
		for warning in sim.take_infrastructure_warnings():
			infrastructure_warning.emit(
				str(warning.get("target_id", "")),
				int(warning.get("uid", 0)))
		for strike in sim.take_infrastructure_strikes():
			infrastructure_strike.emit(
				str(strike.get("target_id", "")),
				float(strike.get("damage", 0.0)),
				int(strike.get("uid", 0)))
		if core != null:
			var dh := _last_core_hp - sim.core_hp
			if _last_core_hp >= 0.0 and dh > 0.0:
				var consumed := consume_fractional_damage(_core_damage_debt, dh)
				_core_damage_debt = float(consumed.debt)
				var whole := int(consumed.whole)
				if whole > 0:
					core.apply_core_damage(whole)
			_last_core_hp = sim.core_hp
		if ladder_print and _tick % 120 == 0:
			print("[CROWDSTAT] t=%.1f alive=%d snap_bytes=%d" % [float(_tick) / 60.0, sim.active, _last_snap_bytes])
		return
	if _uid.is_empty():
		return
	_tick += 1
	_spawned_uids.clear()
	_died_uids.clear()
	for i in count:
		if _state[i] == EnemySnapshotCodec.ST_DEAD:
			_respawn_t[i] -= dt
			if _respawn_t[i] <= 0.0:
				var ang := randf() * TAU
				_xs[i] = cos(ang) * 16.0
				_zs[i] = sin(ang) * 16.0
				_hp[i] = 100.0
				_state[i] = EnemySnapshotCodec.ST_MOVE
				_uid[i] = _next_uid            # new identity after respawn
				_next_uid += 1
				_spawned_uids.append(_uid[i])
			continue
		var dir := Vector3(CORE_POS_X - _xs[i], 0, CORE_POS_Z - _zs[i]).normalized()
		_xs[i] += dir.x * 2.5 * dt
		_zs[i] += dir.z * 2.5 * dt
		if Vector3(_xs[i], 0, _zs[i]).distance_to(CORE_POS) < 2.0 and core:
			core.apply_core_damage(int(ceil(20.0 * dt)))
	if _tick % SNAPSHOT_EVERY_TICKS == 0:
		_broadcast_snapshot()


const CORE_POS := Vector3.ZERO
const CORE_POS_X := 0.0
const CORE_POS_Z := 0.0


## HSNP v1 quantizes positions over [0, arena_size_m]; this lab's world is
## centered at origin, so we shift by ARENA_SIZE_M/2 at the wire boundary.
static func _to_wire(v: float) -> float:
	return clampf(v + ARENA_SIZE_M * 0.5, 0.0, ARENA_SIZE_M)


static func _from_wire(v: float) -> float:
	return v - ARENA_SIZE_M * 0.5


func _broadcast_snapshot() -> void:
	var wx := PackedFloat32Array(); wx.resize(count)
	var wz := PackedFloat32Array(); wz.resize(count)
	for i in count:
		wx[i] = _to_wire(_xs[i])
		wz[i] = _to_wire(_zs[i])
	var bytes := EnemySnapshotCodec.encode_dict({
		"tick": _tick,
		"arena_size_m": ARENA_SIZE_M,
		"uid": _uid, "x": wx, "z": wz,
		"hp": _hp, "state": _state, "flags": _flags, "lane": _lane,
		"spawned": _spawned_uids, "died": _died_uids,
	})
	if _metrics:
		_metrics.add_bytes("crowd_out", bytes.size())
		_metrics.count("crowd_snaps_sent")
	_last_snap_bytes = bytes.size()
	crowd_snapshot.rpc(bytes)
	if ladder_print and _tick % 120 == 0:
		var alive_n := 0
		for k in count:
			if _state[k] != EnemySnapshotCodec.ST_DEAD:
				alive_n += 1
		print("[CROWDSTAT] t=%.1f alive=%d snap_bytes=%d" % [float(_tick) / 60.0, alive_n, _last_snap_bytes])


static func consume_fractional_damage(debt: float, delta: float) -> Dictionary:
	var total := maxf(0.0, debt) + maxf(0.0, delta)
	var whole := int(floor(total + 0.000001))
	return {"whole": whole, "debt": total - float(whole)}


func metrics_enabled() -> bool:
	return _metrics != null


@rpc("any_peer", "call_remote", "unreliable_ordered")
func crowd_snapshot(bytes: PackedByteArray) -> void:
	if multiplayer.get_remote_sender_id() != 1:
		return
	_ingest_snapshot(bytes, true)


func _active_session() -> bool:
	var p := multiplayer.multiplayer_peer
	return p != null and p.get_connection_status() == MultiplayerPeer.CONNECTION_CONNECTED


func _process(_delta: float) -> void:
	if multiplayer.is_server() and not sim_mode:
		_render_arrays(_xs, _zs, _state, _flags)
		return
	if _snaps.is_empty():
		return
	var newest: Dictionary = _snaps[_snaps.size() - 1]
	if _snaps.size() == 1:
		_render_arrays(newest.x, newest.z, newest.state,
			newest.get("flags", PackedByteArray()))
		return
	var older: Dictionary = _snaps[_snaps.size() - 2]
	var sampled := CrowdInterp.sample_interp(
		older, newest, Time.get_ticks_msec(), INTERP_DELAY_MS)
	if sampled.is_empty():
		_render_arrays(newest.x, newest.z, newest.state,
			newest.get("flags", PackedByteArray()))
	else:
		_render_arrays(sampled.x, sampled.z, sampled.state,
			sampled.get("flags", PackedByteArray()))


func _ensure_render_capacity(required: int) -> void:
	for mm_v in _role_mms.values():
		var mm := mm_v as MultiMesh
		if mm != null and required > mm.instance_count:
			mm.instance_count = required
	if _armored_weak_mm != null and required > _armored_weak_mm.instance_count:
		_armored_weak_mm.instance_count = required


func _role_from_flags(flags_v: int) -> String:
	if (flags_v & CrowdSim.F_ROLE_ARMORED) != 0:
		return "ARMORED"
	if (flags_v & CrowdSim.F_ROLE_HARASSER) != 0:
		return "HARASSER"
	return "PRESSURE"


func _render_arrays(xs, zs, states, role_flags = PackedByteArray()) -> void:
	var n := mini(xs.size(), mini(zs.size(), states.size()))
	_ensure_render_capacity(n)
	var counts := {"PRESSURE": 0, "ARMORED": 0, "HARASSER": 0}
	var weak_count := 0
	var now := float(Time.get_ticks_msec()) * 0.004

	for i in n:
		if states[i] == EnemySnapshotCodec.ST_DEAD:
			continue
		var flags_v := int(role_flags[i]) if i < role_flags.size() else 0
		var role := _role_from_flags(flags_v)
		var mm := _role_mms.get(role) as MultiMesh
		if mm == null:
			continue
		var slot := int(counts[role])
		counts[role] = slot + 1

		var pos := Vector3(float(xs[i]), 0.54, float(zs[i]))
		var basis := Basis.IDENTITY
		match role:
			"ARMORED":
				pos.y = 0.78
			"HARASSER":
				pos.y = 2.35 + sin(now + float(i) * 0.73) * 0.14
				basis = Basis.IDENTITY.scaled(Vector3(1.45, 1.0, 0.76))
			_:
				pass
		mm.set_instance_transform(slot, Transform3D(basis, pos))

		if role == "ARMORED" and _armored_weak_mm != null:
			_armored_weak_mm.set_instance_transform(
				weak_count,
				Transform3D(Basis.IDENTITY, Vector3(pos.x, 1.47, pos.z)))
			weak_count += 1

	for role in counts:
		var mm := _role_mms.get(role) as MultiMesh
		if mm != null:
			mm.visible_instance_count = int(counts[role])
	if _armored_weak_mm != null:
		_armored_weak_mm.visible_instance_count = weak_count
	_rendered_count = n


func enemy_position(i: int) -> Vector3:
	# Authority-side hit test reads the active backend; clients never resolve hits.
	if sim_mode and sim != null:
		if i < 0 or i >= sim.active:
			return Vector3.ZERO
		var half := sim.field.size_m * 0.5
		var y := 2.2 if sim.role_of_slot(i) == CrowdSim.ROLE_HARASSER else 0.5
		return Vector3(sim.px[i] - half, y, sim.pz[i] - half)
	if i < 0 or i >= _xs.size():
		return Vector3.ZERO
	return Vector3(_xs[i], 0.5, _zs[i])


func enemy_role(i: int) -> String:
	if sim_mode and sim != null and i >= 0 and i < sim.active:
		return CrowdSim.role_name(sim.role_of_slot(i))
	return "PRESSURE"


func world_los_clear(from: Vector3, to: Vector3, collision_mask: int = 1,
		exclude: Array[RID] = []) -> bool:
	if not is_inside_tree():
		return true
	var q := PhysicsRayQueryParameters3D.create(from, to, collision_mask, exclude)
	q.collide_with_areas = false
	q.collide_with_bodies = true
	return get_world_3d().direct_space_state.intersect_ray(q).is_empty()


func find_enemy_in_cone_los(origin: Vector3, forward: Vector3, max_range: float,
		min_dot: float = 0.94, exclude: Array[RID] = []) -> int:
	if not multiplayer.is_server() or not sim_mode or sim == null:
		return -1
	var best := -1
	var best_d := max_range
	var flat_fwd := Vector3(forward.x, 0.0, forward.z).normalized()
	for i in range(sim.active):
		var target := enemy_position(i)
		var to_enemy := target - origin
		var flat := Vector3(to_enemy.x, 0.0, to_enemy.z)
		var d := flat.length()
		if d <= 0.001 or d >= best_d:
			continue
		if flat_fwd.dot(flat / d) < min_dot:
			continue
		if not world_los_clear(origin, target + Vector3.UP * 0.25, 1, exclude):
			continue
		best = i
		best_d = d
	return best


## Host-authoritative camera-ray resolver for the packed crowd.
## Crowd agents deliberately stay data-only; this performs cheap ray-vs-role
## proxy tests after clamping the ray at the first world collision.
func raycast_enemy(origin: Vector3, direction: Vector3, max_range: float,
		exclude: Array[RID] = []) -> Dictionary:
	if not multiplayer.is_server() or not sim_mode or sim == null:
		return {"index": -1, "end": origin + direction.normalized() * max_range,
			"weakpoint": false}
	var dir := direction.normalized()
	if dir.length_squared() <= 0.0001:
		return {"index": -1, "end": origin, "weakpoint": false}

	var max_dist := max_range
	var wall_end := origin + dir * max_dist
	if is_inside_tree():
		var q := PhysicsRayQueryParameters3D.create(origin, wall_end, 1, exclude)
		q.collide_with_areas = false
		q.collide_with_bodies = true
		var wall_hit := get_world_3d().direct_space_state.intersect_ray(q)
		if not wall_hit.is_empty():
			wall_end = wall_hit.position
			max_dist = origin.distance_to(wall_end)

	var best := -1
	var best_along := max_dist
	var best_weakpoint := false
	for i in range(sim.active):
		var role := enemy_role(i)
		var center := enemy_position(i)
		var radius := 0.58
		match role:
			"ARMORED":
				center.y = 1.05
				radius = 0.95
			"HARASSER":
				radius = 0.72
			_:
				center.y = 0.82
		var to_center := center - origin
		var along := to_center.dot(dir)
		if along <= 0.0 or along >= best_along:
			continue
		var closest := origin + dir * along
		if closest.distance_squared_to(center) > radius * radius:
			continue
		best = i
		best_along = along
		best_weakpoint = false
		if role == "ARMORED":
			var weak_center := center + Vector3.UP * 0.42
			var weak_along := (weak_center - origin).dot(dir)
			var weak_closest := origin + dir * weak_along
			best_weakpoint = weak_along > 0.0 				and weak_closest.distance_squared_to(weak_center) <= 0.34 * 0.34

	if best < 0:
		return {"index": -1, "end": wall_end, "weakpoint": false}
	return {
		"index": best,
		"end": origin + dir * best_along,
		"weakpoint": best_weakpoint,
	}



func find_nearest_role_enemy(world_pos: Vector3, max_range: float,
		role_name_filter: String, require_los: bool = true,
		exclude: Array[RID] = []) -> int:
	if not multiplayer.is_server() or not sim_mode or sim == null:
		return -1
	var best := -1
	var best_d2 := max_range * max_range
	for i in range(sim.active):
		if enemy_role(i) != role_name_filter:
			continue
		var p := enemy_position(i)
		var dx := p.x - world_pos.x
		var dz := p.z - world_pos.z
		var d2 := dx * dx + dz * dz
		if d2 >= best_d2:
			continue
		if require_los and not world_los_clear(
				world_pos + Vector3.UP, p + Vector3.UP * 0.25, 1, exclude):
			continue
		best_d2 = d2
		best = i
	return best


func enemy_uid(i: int) -> int:
	if sim_mode and sim != null and i >= 0 and i < sim.active:
		return sim.uid[i]
	if i >= 0 and i < _uid.size():
		return _uid[i]
	return -1


func lane_densities() -> Dictionary:
	var counts := {"A": 0, "B": 0, "C": 0}
	if multiplayer.is_server() and sim_mode and sim != null:
		for i in range(sim.active):
			var li := clampi(int(sim.lane[i]), 0, 2)
			counts[["A", "B", "C"][li]] += 1
	elif not _snaps.is_empty():
		var lanes: PackedByteArray = _snaps[-1].get("lane", PackedByteArray())
		for li_v in lanes:
			var li := clampi(int(li_v), 0, 2)
			counts[["A", "B", "C"][li]] += 1
	# Readability uses absolute per-lane pressure, not share of the current
	# population: 2 enemies on an otherwise empty map must not look like 100%.
	const DENSE_LANE_COUNT := 20.0
	return {
		"A": clampf(float(counts.A) / DENSE_LANE_COUNT, 0.0, 1.0),
		"B": clampf(float(counts.B) / DENSE_LANE_COUNT, 0.0, 1.0),
		"C": clampf(float(counts.C) / DENSE_LANE_COUNT, 0.0, 1.0),
	}


func find_enemy_in_cone(origin: Vector3, forward: Vector3, max_range: float,
		min_dot: float = 0.94) -> int:
	if not multiplayer.is_server() or not sim_mode or sim == null:
		return -1
	var best := -1
	var best_d := max_range
	var flat_fwd := Vector3(forward.x, 0.0, forward.z).normalized()
	for i in range(sim.active):
		var to_enemy := enemy_position(i) - origin
		to_enemy.y = 0.0
		var d := to_enemy.length()
		if d > 0.001 and d < best_d and flat_fwd.dot(to_enemy / d) >= min_dot:
			best = i
			best_d = d
	return best


func damage_in_radius(center: Vector3, radius: float, damage: float,
		source_kind: String) -> int:
	if not multiplayer.is_server() or not sim_mode or sim == null:
		return 0
	var ids: Array[int] = []
	var r2 := radius * radius
	for i in range(sim.active):
		var p := enemy_position(i)
		var dx := p.x - center.x
		var dz := p.z - center.z
		if dx * dx + dz * dz <= r2:
			ids.append(sim.uid[i])
	var hits := 0
	for target_uid in ids:
		if sim.slot_of_uid(target_uid) >= 0:
			if sim.damage(target_uid, damage, source_kind, false):
				enemy_killed.rpc(target_uid, source_kind)
			hits += 1
	return hits


func find_nearest_enemy(world_pos: Vector3, max_range: float,
		require_unslowed: bool = false, excluded_role: String = "") -> int:
	if not multiplayer.is_server() or not sim_mode or sim == null:
		return -1
	var best := -1
	var best_d2 := max_range * max_range
	var half := sim.field.size_m * 0.5
	for i in range(sim.active):
		if require_unslowed and sim.is_slowed_slot(i):
			continue
		if excluded_role != "" and enemy_role(i) == excluded_role:
			continue
		var dx := (sim.px[i] - half) - world_pos.x
		var dz := (sim.pz[i] - half) - world_pos.z
		var d2 := dx * dx + dz * dz
		if d2 < best_d2:
			best_d2 = d2
			best = i
	return best


func apply_slow(i: int, factor: float, duration: float) -> bool:
	if not multiplayer.is_server() or not sim_mode or sim == null:
		return false
	if i < 0 or i >= sim.active:
		return false
	return sim.apply_slow(sim.uid[i], factor, duration)


func enemy_is_slowed(i: int) -> bool:
	return sim_mode and sim != null and sim.is_slowed_slot(i)


func weakpoint_alignment_required(i: int) -> bool:
	return enemy_role(i) == "ARMORED"


func weakpoint_hit(i: int, shooter_pos: Vector3, shooter_forward: Vector3) -> bool:
	if not weakpoint_alignment_required(i):
		return false
	var to_enemy := enemy_position(i) - shooter_pos
	to_enemy.y = 0.0
	if to_enemy.length_squared() <= 0.0001:
		return false
	# Temporary greybox proxy for the lab's glowing weak-point: a much tighter
	# aim cone than a body hit. Replaced by real hit geometry in the visual pass.
	return shooter_forward.normalized().dot(to_enemy.normalized()) >= 0.97


func apply_damage(i: int, dmg: int, shooter: Node, weakpoint: bool = false,
		source_kind: String = "pilot") -> void:
	if not multiplayer.is_server():
		return
	if sim_mode and sim != null:
		if i < 0 or i >= sim.active:
			return
		var target_uid := sim.uid[i]
		if sim.damage(target_uid, float(dmg), source_kind, weakpoint):
			enemy_killed.rpc(target_uid, shooter.name if shooter else "?")
		return
	if _uid.is_empty() or i < 0 or i >= _uid.size():
		return
	_hp[i] = maxf(0.0, _hp[i] - float(dmg))
	if _hp[i] <= 0.0 and _state[i] != EnemySnapshotCodec.ST_DEAD:
		_state[i] = EnemySnapshotCodec.ST_DEAD      # canon value 2
		_respawn_t[i] = 3.0
		_died_uids.append(_uid[i])
		enemy_killed.rpc(_uid[i], shooter.name if shooter else "?")


@rpc("authority", "call_remote", "reliable")
func enemy_killed(uid: int, by: String) -> void:
	if _metrics:
		_metrics.count("enemy_kill_events")
	print("EVENT enemy_killed uid=%d by=%s" % [uid, by])
